#include <stdio.h>

int main(void) {
    int stock = 2;
    int other = 9;
    int fresh = 5;
    // 원래 재고의 위치를 가리켜요.
    int *p = &stock;
    // 이 주석 아래에 p가 가리키는 곳에 fresh를 쓰는 줄을 쓰세요.
