tasks.solution:
#include <stdio.h>

int main(void) {
    // 두 재고는 서로 다른 변수예요.
    int stock = 2;
    int other = 7;
    int *p = &stock;
    // 이 줄을 고쳐 stock은 그대로 두고 p가 other를 가리키게 하세요.
    // 별표 없이 p에 대입하면 가리키는 곳만 바뀌어요. stock의 값은 그대로예요.
    p = &other;
    printf("%d\n%d", *p, stock);
    return 0;
}

