tasks.solution:
#include <stdio.h>

int main(void) {
    // 같은 배열 안의 위치를 골라요.
    int bins[] = {2, 5, 7};
    int *p = bins;
    // 이 줄을 고쳐 p에서 한 칸 뒤의 값을 포인터 덧셈으로 읽으세요.
    // p + 1은 int 한 칸 뒤의 주소예요. 별표로 그곳의 값을 읽어요.
    int next = *(p + 1);
    printf("%d", next);
    return 0;
}

tasks.starter_code:
#include <stdio.h>

int main(void) {
    // 첫 원소와 다음 원소는 서로 다른 값이에요.
    int bins[] = {2, 5};
    int *p = bins;
    // 이 줄을 고쳐 값이 아니라 포인터를 한 원소 앞으로 옮기세요.
    (*p)++;
    printf("%d\n%d", *p, bins[0]);
    return 0;
}

tasks.solution:
#include <stdio.h>

int main(void) {
    // 첫 원소와 다음 원소는 서로 다른 값이에요.
    int bins[] = {2, 5};
    int *p = bins;
    // 이 줄을 고쳐 값이 아니라 포인터를 한 원소 앞으로 옮기세요.
    // p++는 p가 다음 원소를 가리키게 해요. 배열 값은 바뀌지 않아요.
    p++;
    printf("%d\n%d", *p, bins[0]);
    return 0;
}

