// p는 호출자가 전달한 포인터 값의 복사예요. 바꾼 포인터를 돌려줘요.
int *redirect(int *p, int *other) {
    p = other;
    return p;
}

int main(void) {
    int stock = 2;
    int other = 7;
    int *p = &stock;
    // 이 줄을 고쳐 redirect가 돌려준 포인터를 main의 p에 저장하세요.
    redirect(p, &other);
    printf("%d", *p);
    return 0;
}

