#include <stdio.h>

// 복사한 주소로 원래 대상의 값을 바꿔요.
void add(int *p) {
    // 이 주석 아래에 p가 가리키는 값을 1 올리는 줄을 쓰세요.
    // 주소는 복사본이어도 같은 stock을 가리켜요. *p에 쓰면 main의 stock이 바뀌어요.
    *p = *p + 1;
}

int main(void) {
    // 원래 stock의 주소를 전달해요.
    int stock = 2;
    add(&stock);
    printf("%d", stock);
    return 0;
}

