#include <stdio.h>
void swap(int *a, int *b) {
    int temp = *a;
    a = b;
    *b = temp;
}
int main(void) {
    int left = 3, right = 8;
    swap(&left, &right);
    printf("%d %d", left, right);
    return 0;
}

tasks.solution:
#include <stdio.h>
void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}
int main(void) {
    int left = 3, right = 8;
    swap(&left, &right);
    printf("%d %d", left, right);
    return 0;
}
